bounded_host_request.command:
set -eu
cid=gace-createvdobot-videobot-poll-1
test "$(docker inspect "$cid" --format '{{.State.Running}}')" = true || exit 41
docker exec -i -w /opt/videobot "$cid" node --input-type=module <<'NODE'
import fs from 'node:fs';
import pg from 'pg';
const env=process.env;
if(env.VIDEOBOT_DB_NAME!=='videobot')throw Error('VIDEO_DB_OWNER_UNVERIFIED');
const pool=new pg.Pool({host:env.VIDEOBOT_DB_HOST,user:env.VIDEOBOT_DB_USER,
 database:env.VIDEOBOT_DB_NAME,
 password:fs.readFileSync('/run/secrets/videobot_db_password','utf8').trim(),
 max:1,connectionTimeoutMillis:4500});
const client=await pool.connect();let committed=false;
try{
 const target=(await client.query("SELECT current_database() AS db,current_schema() AS schema")).rows[0];
 if(target.db!=='videobot'||target.schema!=='public')throw Error('VIDEO_DB_SCHEMA_UNVERIFIED');
 const before=(await client.query("SELECT column_name FROM information_schema.columns WHERE table_schema='public' AND table_name='videobot_listings' AND column_name IN ('creator_terms_version','creator_terms_url') ORDER BY column_name")).rows;
 console.log('TERMS_COLUMNS_BEFORE='+before.length);
 await client.query('BEGIN');
 await client.query("ALTER TABLE videobot_listings ADD COLUMN IF NOT EXISTS creator_terms_version TEXT NULL CHECK (creator_terms_version IS NULL OR char_length(creator_terms_version) BETWEEN 1 AND 32), ADD COLUMN IF NOT EXISTS creator_terms_url TEXT NULL CHECK (creator_terms_url IS NULL OR char_length(creator_terms_url) BETWEEN 1 AND 512)");
 await client.query('COMMIT');committed=true;
 const after=(await client.query("SELECT column_name FROM information_schema.columns WHERE table_schema='public' AND table_name='videobot_listings' AND column_name IN ('creator_terms_version','creator_terms_url') ORDER BY column_name")).rows;
 if(after.length!==2)throw Error('VIDEO_TERMS_SCHEMA_NOT_VERIFIED');
 console.log('TERMS_COLUMNS_AFTER='+after.length);
 const old=(await client.query("SELECT COUNT(*)::int n FROM videobot_stars_ledger WHERE kind='paid'")).rows[0].n;
 console.log('HISTORICAL_VIDEO_PAID_ROWS='+old);
 const newRow=(await client.query("SELECT COUNT(*)::int n FROM videobot_listings WHERE listing_id='v26nov24invoice'")).rows[0].n;
 console.log('REISSUE_LISTING_ROW_COUNT='+newRow);
}finally{if(!committed)await client.query('ROLLBACK').catch(()=>{});client.release();await pool.end();}
NODE
